arguments.old_text:
# Move monsters
for monster in monsters:
    monster.x += MONSTER_SPEED
    if monster.left > SCREEN_WIDTH:
        monster.x = 0
    if monster.top > SCREEN_HEIGHT:
        monster.y = 0
    if monster.bottom < 0:
        monster.y = SCREEN_HEIGHT
    if monster.right < 0:
        monster.x = SCREEN_WIDTH

# Check collisions
for monster in monsters[:]:  # Iterate over a copy
    if player.colliderect(monster):
        # Player hit by monster
        monsters.remove(monster)
        lives -= 1
        if lives <= 0:
            running = False

